document.getElementById("newsList").insertAdjacentHTML("beforeend", "<article class=\"news-card\" style=\"--stripe:#e60ba0;--thumb-a:#3a0825;--thumb-b:#1e0413\" data-search=\"google gemini 4 hydrogen search ai mode overviews query fan-out default model robby stein search engine journal\">\n        <a class=\"thumb\" href=\"/news/2026-11-13-gemini-4-hydrogen-ai-mode.html\" aria-label=\"Read: Gemini 4 Hydrogen is now the default in Search's AI Mode\">\n          <div class=\"thumb-inner\">G</div>\n        </a>\n        <div class=\"article-body\">\n          <div class=\"article-meta\">Google / Search <span>13 Nov 2026</span></div>\n          <h3>Gemini 4 Hydrogen is now the default in Search's AI Mode</h3>\n          <p class=\"summary\">Google announcement, 12 November 2026 (Robby Stein, VP of Product, Google Search). Google calls it \"the biggest model upgrade to Search yet\". Available globally in Search for all users. Google says it handles multi-part questions, typos and highly specific requests better; its improved query fan-out connects people to \"a broader range of helpful links than before\", including sites they might not have found; and responses get more images, structured answers, comparison tables and custom tools. Search Engine Journal reports Stein said it is now the default model in AI Mode and is used for the hardest questions in AI Overviews, and that it arrived two days into Google's November core update. Neither Google's post nor Stein's thread gives counts for links or sites (per SEJ). Hydrogen is also in the Gemini app, AI Studio, the Gemini API and Gemini for business; API price $1.50 per million input tokens and $7.50 per million output tokens (Google's figures).</p>\n          <div class=\"card-actions\">\n            <a class=\"read-more\" href=\"/news/2026-11-13-gemini-4-hydrogen-ai-mode.html\">Read full article</a>\n            <div class=\"reaction-row\"><a class=\"reaction\" href=\"https://blog.google/products-and-platforms/products/search/gemini-4-hydrogen-search-upgrade/\" target=\"_blank\" rel=\"noopener\">Source: Google</a><span class=\"reaction\">Make your business easy for AI to read, and decide where it's allowed to act.</span></div>\n          </div>\n        </div>\n      </article>\n\n      ");
document.getElementById("newsList").insertAdjacentHTML("beforeend", "<article class=\"news-card\" style=\"--stripe:#06b6d4;--thumb-a:#0c2a3e;--thumb-b:#071822\" data-search=\"united airlines unauthorised unauthorized third-party ai agents booking flights travel agencies aggregators washington post\">\n        <a class=\"thumb\" href=\"/news/2026-11-13-united-unauthorised-ai-agents.html\" aria-label=\"Read: United Airlines bars unauthorised AI agents from booking its flights\">\n          <div class=\"thumb-inner\">U</div>\n        </a>\n        <div class=\"article-body\">\n          <div class=\"article-meta\">United / Booking <span>13 Nov 2026</span></div>\n          <h3>United Airlines bars unauthorised AI agents from booking its flights</h3>\n          <p class=\"summary\">United help-centre page on third-party AI agents (bookings made by AI agents before 11 November 2026 won't be cancelled). United says it is restricting access, directly and via travel agencies and aggregators, by unauthorised third-party AI agents or assistants that search, book, buy, manage or collect information on united.com or the app. Customers can still use AI to research and plan, as long as the tool doesn't access United's site or app. United cites privacy, security and regulation, e.g. check-in requires a person to confirm bags hold no banned items. Assistive technology for customers with disabilities isn't affected. United says it doesn't yet work with any third-party AI agents. Also reported by The Washington Post (12 Nov).</p>\n          <div class=\"card-actions\">\n            <a class=\"read-more\" href=\"/news/2026-11-13-united-unauthorised-ai-agents.html\">Read full article</a>\n            <div class=\"reaction-row\"><a class=\"reaction\" href=\"https://www.united.com/en/us/fly/help-center/digital-trust-center/artificial-intelligence/third-party-ai-agents.html\" target=\"_blank\" rel=\"noopener\">Source: United Airlines</a><span class=\"reaction\">Make your business easy for AI to read, and decide where it's allowed to act.</span></div>\n          </div>\n        </div>\n      </article>\n\n      ");
document.getElementById("newsList").insertAdjacentHTML("beforeend", "<article class=\"news-card\" style=\"--stripe:#f59e0b;--thumb-a:#3d2000;--thumb-b:#1c0e00\" data-search=\"elevenlabs scribe v3 live speech-to-text semantic wer speaker labels turn detection keyterm eneco postcodes\">\n        <a class=\"thumb\" href=\"/news/2026-11-13-elevenlabs-scribe-v3.html\" aria-label=\"Read: ElevenLabs launches Scribe v3 and Scribe v3 Live speech-to-text\">\n          <div class=\"thumb-inner\">E</div>\n        </a>\n        <div class=\"article-body\">\n          <div class=\"article-meta\">ElevenLabs / Voice <span>13 Nov 2026</span></div>\n          <h3>ElevenLabs launches Scribe v3 and Scribe v3 Live speech-to-text</h3>\n          <p class=\"summary\">ElevenLabs blog (Min Kim), 10 November 2026. Scribe v3 (recorded audio) makes 27% fewer word errors than Scribe v2 across 102 languages; Scribe v3 Live (realtime) makes 43% fewer errors (semantic WER; 31% on standard WER) than Scribe v2 Realtime, ElevenLabs' own tests, and adds speaker labels in Scribe's realtime model for the first time. Scribe v3 Live's turn detection uses the conversation's context as well as silence, so a caller who pauses halfway through a number isn't cut off. Keyterm prompting takes up to 1,000 terms. Eneco (Dutch energy supplier) says its voice agent recognised postcodes correctly first time 40% more often in testing. Live in ElevenAgents; both in ElevenAPI.</p>\n          <div class=\"card-actions\">\n            <a class=\"read-more\" href=\"/news/2026-11-13-elevenlabs-scribe-v3.html\">Read full article</a>\n            <div class=\"reaction-row\"><a class=\"reaction\" href=\"https://elevenlabs.io/blog/scribe-v3\" target=\"_blank\" rel=\"noopener\">Source: ElevenLabs</a><span class=\"reaction\">Make your business easy for AI to read, and decide where it's allowed to act.</span></div>\n          </div>\n        </div>\n      </article>\n\n      ");
document.getElementById("newsList").insertAdjacentHTML("beforeend", "<article class=\"news-card\" style=\"--stripe:#ef4444;--thumb-a:#3a0a0a;--thumb-b:#1a0404\" data-search=\"google gemini live apple carplay rolling out ios calendar email summaries android auto daily brief\">\n        <a class=\"thumb\" href=\"/news/2026-11-13-gemini-live-apple-carplay.html\" aria-label=\"Read: Gemini Live is rolling out to Apple CarPlay\">\n          <div class=\"thumb-inner\">G</div>\n        </a>\n        <div class=\"article-body\">\n          <div class=\"article-meta\">Google / CarPlay <span>13 Nov 2026</span></div>\n          <h3>Gemini Live is rolling out to Apple CarPlay</h3>\n          <p class=\"summary\">Google blog (Karan Daryanani), 11 November 2026. Gemini Live is rolling out globally on Apple CarPlay for all Gemini users on iOS, in every supported Gemini Live language. Hands-free conversations to check your calendar, summarise emails, talk through a reply, get local recommendations or rehearse a meeting; chats sync to the iPhone Gemini app. Needs the latest Gemini app, microphone permission, and Gemini Live used on the phone at least once. Follows Android Auto and cars with Google built-in. Daily Brief isn't available to under-18s or in the EEA and Nigeria.</p>\n          <div class=\"card-actions\">\n            <a class=\"read-more\" href=\"/news/2026-11-13-gemini-live-apple-carplay.html\">Read full article</a>\n            <div class=\"reaction-row\"><a class=\"reaction\" href=\"https://blog.google/innovation-and-ai/products/gemini-app/gemini-on-apple-carplay/\" target=\"_blank\" rel=\"noopener\">Source: Google</a><span class=\"reaction\">Make your business easy for AI to read, and decide where it's allowed to act.</span></div>\n          </div>\n        </div>\n      </article>\n\n      ");
document.getElementById("newsList").insertAdjacentHTML("beforeend", "<article class=\"news-card\" style=\"--stripe:#10b981;--thumb-a:#064e3b;--thumb-b:#051e16\" data-search=\"microsoft copilot reminder personal account sign in 31 december 2026 eligible chats content deleted tasks cowork premium pro\">\n        <a class=\"thumb\" href=\"/news/2026-11-13-copilot-sign-in-reminder.html\" aria-label=\"Read: Reminder: if you used the older Microsoft Copilot with a personal account, sign in by 31 December\">\n          <div class=\"thumb-inner\">M</div>\n        </a>\n        <div class=\"article-body\">\n          <div class=\"article-meta\">Microsoft / Reminder <span>13 Nov 2026</span></div>\n          <h3>Reminder: if you used the older Microsoft Copilot with a personal account, sign in by 31 December</h3>\n          <p class=\"summary\">Microsoft Support page (undated; not new this week, flagged as a practical reminder, reported again by Tech-news.kz on 12 Nov). Microsoft is moving Copilot users to one updated Copilot app. Personal-account users must sign in to the updated app by 31 December 2026 to keep eligible chats and content; content not migrated will be permanently deleted after that date. Copilot Tasks with personal accounts is moving to Cowork (preview) over the next few weeks; Cowork is a Premium or Pro feature, so Personal or Family subscribers can view earlier Tasks content but need Microsoft 365 Premium or Pro to run new tasks. Scheduled tasks move but are turned off by default.</p>\n          <div class=\"card-actions\">\n            <a class=\"read-more\" href=\"/news/2026-11-13-copilot-sign-in-reminder.html\">Read full article</a>\n            <div class=\"reaction-row\"><a class=\"reaction\" href=\"https://support.microsoft.com/en-us/microsoft-365-copilot/learning/changes-microsoft-copilot-app\" target=\"_blank\" rel=\"noopener\">Source: Microsoft Support</a><span class=\"reaction\">Make your business easy for AI to read, and decide where it's allowed to act.</span></div>\n          </div>\n        </div>\n      </article>\n\n      ");
