document.getElementById("newsList").insertAdjacentHTML("beforeend", "<article class=\"news-card\" style=\"--stripe:#e60ba0;--thumb-a:#3a0825;--thumb-b:#1e0413\" data-search=\"ico subject access request sar ai-assisted guidance clarification metadata manifestly unfounded templates\">\n        <a class=\"thumb\" href=\"/news/2026-11-12-ico-ai-assisted-sars.html\" aria-label=\"Read: ICO publishes guidance on AI-assisted subject access requests\">\n          <div class=\"thumb-inner\">I</div>\n        </a>\n        <div class=\"article-body\">\n          <div class=\"article-meta\">ICO / SARs <span>12 Nov 2026</span></div>\n          <h3>ICO publishes guidance on AI-assisted subject access requests</h3>\n          <p class=\"summary\">Information Commissioner's Office guidance, published 11 November 2026. A subject access request (SAR) isn't invalid just because someone used AI to draft it; organisations must treat it like any other SAR. The ICO notes AI-assisted SARs can be lengthy, broad, unclear or include irrelevant legal references or laws from other jurisdictions. It covers asking for clarification, when a request may be complex, reasonable and proportionate searches, metadata requests, and when a request may be manifestly unfounded or excessive. Practical steps it suggests: clear guidance on how to make a SAR and a point of contact, staff training, optional example prompts or templates, and reminding people to review an AI-assisted SAR before sending it.</p>\n          <div class=\"card-actions\">\n            <a class=\"read-more\" href=\"/news/2026-11-12-ico-ai-assisted-sars.html\">Read full article</a>\n            <div class=\"reaction-row\"><a class=\"reaction\" href=\"https://ico.org.uk/for-organisations/uk-gdpr-guidance-and-resources/subject-access-requests/subject-access-requests-generated-by-artificial-intelligence/\" target=\"_blank\" rel=\"noopener\">Source: ICO</a><span class=\"reaction\">Keep things simple and clear, and keep a person approving anything that matters.</span></div>\n          </div>\n        </div>\n      </article>\n\n      ");
document.getElementById("newsList").insertAdjacentHTML("beforeend", "<article class=\"news-card\" style=\"--stripe:#06b6d4;--thumb-a:#0c2a3e;--thumb-b:#071822\" data-search=\"anthropic claude interactive connectors mcp apps asana canva dropbox hubspot notion admins restrict all plans\">\n        <a class=\"thumb\" href=\"/news/2026-11-12-claude-interactive-connectors.html\" aria-label=\"Read: Claude can now open your apps beside the chat and work in them\">\n          <div class=\"thumb-inner\">C</div>\n        </a>\n        <div class=\"article-body\">\n          <div class=\"article-meta\">Anthropic / Claude <span>12 Nov 2026</span></div>\n          <h3>Claude can now open your apps beside the chat and work in them</h3>\n          <p class=\"summary\">Anthropic announcement, 10 November 2026 (\"Starting today\"). Where a connector supports it, users can open a tool beside the conversation or full screen and ask Claude to make changes, approving its actions as they would a connector's. Rolling out on the web and Claude desktop app on all plans, as part of the new Claude experience. Anthropic says it's starting with a small group of tools including Asana, Canva, Carta, Dropbox, monday.com, Smartsheet, Vercel and Webflow, and gives examples for Adobe, Atlassian (Confluence), Box, HubSpot and Notion. Admins can restrict a connector's tools as they do today. Built on MCP Apps, an open extension to the Model Context Protocol.</p>\n          <div class=\"card-actions\">\n            <a class=\"read-more\" href=\"/news/2026-11-12-claude-interactive-connectors.html\">Read full article</a>\n            <div class=\"reaction-row\"><a class=\"reaction\" href=\"https://claude.com/resources/articles/interactive-connectors-full-tool\" target=\"_blank\" rel=\"noopener\">Source: Anthropic</a><span class=\"reaction\">Keep things simple and clear, and keep a person approving anything that matters.</span></div>\n          </div>\n        </div>\n      </article>\n\n      ");
document.getElementById("newsList").insertAdjacentHTML("beforeend", "<article class=\"news-card\" style=\"--stripe:#f59e0b;--thumb-a:#3d2000;--thumb-b:#1c0e00\" data-search=\"openai chatgpt advanced standard voice retire 11 december live gpt-live custom gpts android authority\">\n        <a class=\"thumb\" href=\"/news/2026-11-12-chatgpt-voice-retirement.html\" aria-label=\"Read: OpenAI is retiring ChatGPT's Advanced and Standard voice on 11 December\">\n          <div class=\"thumb-inner\">O</div>\n        </a>\n        <div class=\"article-body\">\n          <div class=\"article-meta\">OpenAI / Voice <span>12 Nov 2026</span></div>\n          <h3>OpenAI is retiring ChatGPT's Advanced and Standard voice on 11 December</h3>\n          <p class=\"summary\">OpenAI Help Center and ChatGPT release notes, 10 November 2026. Advanced and Standard voice retire on 11 December 2026; anyone who selected them will default to Live voice, powered by GPT-Live. OpenAI says voice usage has nearly doubled since GPT-Live launched in July (OpenAI's figure). Live video and screen sharing stay on Advanced voice until GPT-Live supports them. Existing conversations stay in history. Voice with custom GPTs uses Advanced voice until custom GPTs' deprecation on 11 December 2026. Also reported by Android Authority.</p>\n          <div class=\"card-actions\">\n            <a class=\"read-more\" href=\"/news/2026-11-12-chatgpt-voice-retirement.html\">Read full article</a>\n            <div class=\"reaction-row\"><a class=\"reaction\" href=\"https://help.openai.com/en/articles/20001638-retiring-advanced-and-standard-voice-in-chatgpt\" target=\"_blank\" rel=\"noopener\">Source: OpenAI Help Center</a><span class=\"reaction\">Keep things simple and clear, and keep a person approving anything that matters.</span></div>\n          </div>\n        </div>\n      </article>\n\n      ");
document.getElementById("newsList").insertAdjacentHTML("beforeend", "<article class=\"news-card\" style=\"--stripe:#ef4444;--thumb-a:#3a0a0a;--thumb-b:#1a0404\" data-search=\"vapi agent loop early access self-improving voice agents resolution rate simulated calls slack human approval 2027\">\n        <a class=\"thumb\" href=\"/news/2026-11-12-vapi-agent-loop.html\" aria-label=\"Read: Vapi opens early access to Agent Loop for self-improving voice agents\">\n          <div class=\"thumb-inner\">V</div>\n        </a>\n        <div class=\"article-body\">\n          <div class=\"article-meta\">Vapi / Voice <span>12 Nov 2026</span></div>\n          <h3>Vapi opens early access to Agent Loop for self-improving voice agents</h3>\n          <p class=\"summary\">Vapi blog, 11 November 2026. Agent Loop is in early access, with general availability planned for early 2027. You describe the job and set a goal such as resolution rate; it builds the agent, scores every call against the goal, groups misses into issues, drafts a fix, tests it with simulated calls, then trials it on a share of live traffic and rolls back automatically if the number drops. Vapi says nothing ships without a person saying yes; decisions land in an inbox that connects to Slack.</p>\n          <div class=\"card-actions\">\n            <a class=\"read-more\" href=\"/news/2026-11-12-vapi-agent-loop.html\">Read full article</a>\n            <div class=\"reaction-row\"><a class=\"reaction\" href=\"https://vapi.ai/blog/agent-loop-launch\" target=\"_blank\" rel=\"noopener\">Source: Vapi</a><span class=\"reaction\">Keep things simple and clear, and keep a person approving anything that matters.</span></div>\n          </div>\n        </div>\n      </article>\n\n      ");
document.getElementById("newsList").insertAdjacentHTML("beforeend", "<article class=\"news-card\" style=\"--stripe:#10b981;--thumb-a:#064e3b;--thumb-b:#051e16\" data-search=\"n8n nod labs apache research preview personal agent sandbox gmail slack costs unite.ai ophir prusak\">\n        <a class=\"thumb\" href=\"/news/2026-11-12-n8n-nod.html\" aria-label=\"Read: n8n Labs releases Nod, an open-source personal agent\">\n          <div class=\"thumb-inner\">N</div>\n        </a>\n        <div class=\"article-body\">\n          <div class=\"article-meta\">n8n / Agents <span>12 Nov 2026</span></div>\n          <h3>n8n Labs releases Nod, an open-source personal agent</h3>\n          <p class=\"summary\">n8n blog (Ophir Prusak), 10 November 2026. Nod is a research preview from n8n Labs, a standalone app separate from n8n, for Mac and Windows (Windows 11 is a preview) or a self-hosted server. Open source under Apache 2.0. It has its own sandbox and browser, works in connected apps such as Gmail, Calendar, Drive and Slack and on websites, and uses the AI provider you choose. Before it sends, pays, posts or deletes anything you didn't ask for, a separate check confirms; n8n says a web page or email can't give it orders. Nod is free; you pay your model provider. n8n says some early testers found tasks cost more than expected. Unite.AI notes the approval check is itself a model and can make mistakes.</p>\n          <div class=\"card-actions\">\n            <a class=\"read-more\" href=\"/news/2026-11-12-n8n-nod.html\">Read full article</a>\n            <div class=\"reaction-row\"><a class=\"reaction\" href=\"https://blog.n8n.io/meet-nod/\" target=\"_blank\" rel=\"noopener\">Source: n8n</a><span class=\"reaction\">Keep things simple and clear, and keep a person approving anything that matters.</span></div>\n          </div>\n        </div>\n      </article>\n\n      ");
