document.getElementById("newsList").insertAdjacentHTML("beforeend", "<article class=\"news-card\" style=\"--stripe:#e60ba0;--thumb-a:#3a0825;--thumb-b:#1e0413\" data-search=\"anthropic claude fable 5.2 mythos 5.2 cnbc ashley capoot opus 5.5 pricing tokens verification\">\n        <a class=\"thumb\" href=\"/news/2026-11-10-anthropic-claude-fable-mythos-5-2.html\" aria-label=\"Read: Anthropic releases Claude Fable 5.2 and Claude Mythos 5.2\">\n          <div class=\"thumb-inner\">A</div>\n        </a>\n        <div class=\"article-body\">\n          <div class=\"article-meta\">Anthropic / Models <span>10 Nov 2026</span></div>\n          <h3>Anthropic releases Claude Fable 5.2 and Claude Mythos 5.2</h3>\n          <p class=\"summary\">Anthropic announcement, 9 November 2026. Fable 5.2 and Mythos 5.2 are the same underlying model. Fable 5.2 is available to all users on all platforms (including AWS, Google Cloud and Microsoft Azure); Mythos 5.2 is limited to organisations verified through Anthropic's Cyber and Life Sciences Verification Programs. Anthropic says they generate outputs up to 30% faster than the 5.1 models and are priced lower at $8 per million input tokens and $40 per million output tokens (CNBC reports this is 20% less than 5.1). Optional fast mode is $16/$80. CNBC (Ashley Capoot) reports Anthropic positions Fable 5.2 for complex technical work, with Claude Opus 5.5 better suited to daily tasks.</p>\n          <div class=\"card-actions\">\n            <a class=\"read-more\" href=\"/news/2026-11-10-anthropic-claude-fable-mythos-5-2.html\">Read full article</a>\n            <div class=\"reaction-row\"><a class=\"reaction\" href=\"https://www.anthropic.com/claude-fable-and-mythos-5-2\" target=\"_blank\" rel=\"noopener\">Source: Anthropic</a><span class=\"reaction\">Big models for hard problems, cheap models for repeat work, and the same basics either way.</span></div>\n          </div>\n        </div>\n      </article>\n\n      ");
document.getElementById("newsList").insertAdjacentHTML("beforeend", "<article class=\"news-card\" style=\"--stripe:#06b6d4;--thumb-a:#0c2a3e;--thumb-b:#071822\" data-search=\"meta muse ember low-cost agent tool calls haiku luna artificial analysis muse-ember-1.0\">\n        <a class=\"thumb\" href=\"/news/2026-11-10-meta-muse-ember.html\" aria-label=\"Read: Meta launches Muse Ember, a low-cost model for repeat agent work\">\n          <div class=\"thumb-inner\">M</div>\n        </a>\n        <div class=\"article-body\">\n          <div class=\"article-meta\">Meta / Models <span>10 Nov 2026</span></div>\n          <h3>Meta launches Muse Ember, a low-cost model for repeat agent work</h3>\n          <p class=\"summary\">Meta announcement, 9 November 2026. Meta calls Muse Ember its smallest and most efficient model, aimed at tool calls, coding subtasks, routing, extraction and long document parsing. Available now as muse-ember-1.0 on the Meta Model API and Muse Code at $0.10 per million input tokens and $0.50 per million output tokens (prompts up to 200K tokens), with a 1M-token context window. Meta claims it gives more intelligence per dollar than Claude Haiku 5.5 or GPT-6 Luna; these are Meta's own comparisons using Artificial Analysis results and Meta internal evaluations, not independent testing.</p>\n          <div class=\"card-actions\">\n            <a class=\"read-more\" href=\"/news/2026-11-10-meta-muse-ember.html\">Read full article</a>\n            <div class=\"reaction-row\"><a class=\"reaction\" href=\"https://research.meta.ai/blog/muse-ember\" target=\"_blank\" rel=\"noopener\">Source: Meta</a><span class=\"reaction\">Big models for hard problems, cheap models for repeat work, and the same basics either way.</span></div>\n          </div>\n        </div>\n      </article>\n\n      ");
document.getElementById("newsList").insertAdjacentHTML("beforeend", "<article class=\"news-card\" style=\"--stripe:#f59e0b;--thumb-a:#3d2000;--thumb-b:#1c0e00\" data-search=\"otter ai 27 languages multilingual web summit lisbon german mandarin cantonese coming soon\">\n        <a class=\"thumb\" href=\"/news/2026-11-10-otter-ai-27-languages.html\" aria-label=\"Read: Otter.ai adds 27 languages, with language-switching transcription coming soon\">\n          <div class=\"thumb-inner\">O</div>\n        </a>\n        <div class=\"article-body\">\n          <div class=\"article-meta\">Otter / Meetings <span>10 Nov 2026</span></div>\n          <h3>Otter.ai adds 27 languages, with language-switching transcription coming soon</h3>\n          <p class=\"summary\">Otter.ai company release dated 10 November 2026 (unveiled at Web Summit Lisbon), also reported by TechCrunch (Lauren Forristal). 13 new languages are available now (including German, Italian, Dutch, Polish, Portuguese (Brazil), Mandarin and Cantonese) and 14 are coming soon, taking Otter to 31 languages in total. A feature that follows speakers as they switch languages in one meeting is marked \"coming soon\", not live. Otter says the new languages come at no extra cost on its plans and that it does not send audio to third parties for processing.</p>\n          <div class=\"card-actions\">\n            <a class=\"read-more\" href=\"/news/2026-11-10-otter-ai-27-languages.html\">Read full article</a>\n            <div class=\"reaction-row\"><a class=\"reaction\" href=\"https://otter.ai/blog/otter-ai-announces-its-biggest-multilingual-leap-yet-27-new-languages-and-multilingual-capabilities\" target=\"_blank\" rel=\"noopener\">Source: Otter.ai</a><span class=\"reaction\">Big models for hard problems, cheap models for repeat work, and the same basics either way.</span></div>\n          </div>\n        </div>\n      </article>\n\n      ");
document.getElementById("newsList").insertAdjacentHTML("beforeend", "<article class=\"news-card\" style=\"--stripe:#ef4444;--thumb-a:#3a0a0a;--thumb-b:#1a0404\" data-search=\"wyndham android app password salesforce wiggins techcrunch unauthorised access applebee\">\n        <a class=\"thumb\" href=\"/news/2026-11-10-wyndham-app-password.html\" aria-label=\"Read: Wyndham app password exposed customer database, TechCrunch reports\">\n          <div class=\"thumb-inner\">W</div>\n        </a>\n        <div class=\"article-body\">\n          <div class=\"article-meta\">Wyndham / Security <span>10 Nov 2026</span></div>\n          <h3>Wyndham app password exposed customer database, TechCrunch reports</h3>\n          <p class=\"summary\">TechCrunch (Zack Whittaker), 9 November 2026. Security researcher Robert Wiggins (What Security) found a password in the source code of Wyndham's Android app that gave access to an internal Salesforce-hosted database holding customer names, email addresses, member numbers, login tokens and company files. The credential was revoked after TechCrunch contacted Wyndham. Wyndham said its security teams have no evidence of any unauthorised access and would not say how long the password was in the app. Wiggins told TechCrunch he used AI tools to find this and a similar flaw in Applebee's app.</p>\n          <div class=\"card-actions\">\n            <a class=\"read-more\" href=\"/news/2026-11-10-wyndham-app-password.html\">Read full article</a>\n            <div class=\"reaction-row\"><a class=\"reaction\" href=\"https://techcrunch.com/2026/11/09/hotel-giant-wyndham-exposed-customer-data-after-app-security-lapse/\" target=\"_blank\" rel=\"noopener\">Source: TechCrunch</a><span class=\"reaction\">Big models for hard problems, cheap models for repeat work, and the same basics either way.</span></div>\n          </div>\n        </div>\n      </article>\n\n      ");
document.getElementById("newsList").insertAdjacentHTML("beforeend", "<article class=\"news-card\" style=\"--stripe:#10b981;--thumb-a:#064e3b;--thumb-b:#051e16\" data-search=\"anthropic usage policy 12 november deceptive campaigns high-risk human review disclosure\">\n        <a class=\"thumb\" href=\"/news/2026-11-10-anthropic-usage-policy-update.html\" aria-label=\"Read: Anthropic's updated Usage Policy takes effect on Thursday 12 November\">\n          <div class=\"thumb-inner\">A</div>\n        </a>\n        <div class=\"article-body\">\n          <div class=\"article-meta\">Anthropic / Policy <span>10 Nov 2026</span></div>\n          <h3>Anthropic's updated Usage Policy takes effect on Thursday 12 November</h3>\n          <p class=\"summary\">Anthropic post published 8 October 2026; the updated policy takes effect on 12 November. It adds a new section on deceptive campaigns and artificial activity covering commercial as well as political use (fake accounts, fake posts, hiding who is behind a message). Its rewritten high-risk section restates existing requirements: where Claude is used in ways that can affect someone's health, legal rights, finances, livelihood or access to essential services, a qualified human must be able to review and change its recommendations, and the person affected must be told AI was used. Anthropic says those requirements have not changed; the section now lists more clearly which uses are covered.</p>\n          <div class=\"card-actions\">\n            <a class=\"read-more\" href=\"/news/2026-11-10-anthropic-usage-policy-update.html\">Read full article</a>\n            <div class=\"reaction-row\"><a class=\"reaction\" href=\"https://www.anthropic.com/news/2026-usage-policy-update\" target=\"_blank\" rel=\"noopener\">Source: Anthropic</a><span class=\"reaction\">Big models for hard problems, cheap models for repeat work, and the same basics either way.</span></div>\n          </div>\n        </div>\n      </article>\n\n      ");
