document.getElementById("newsList").insertAdjacentHTML("beforeend", "<article class=\"news-card\" style=\"--stripe:#e60ba0;--thumb-a:#3a0825;--thumb-b:#1e0413\" data-search=\"openai gpt-6 cyber authorised scoped vulnerability research exploitgym daybreak preparedness linux firefox\">\n        <a class=\"thumb\" href=\"/news/2026-11-06-openai-gpt-6-cyber.html\" aria-label=\"Read: OpenAI GPT-6 Cyber for authorised scoped vulnerability research (5 Nov).\">\n          <div class=\"thumb-inner\">O</div>\n        </a>\n        <div class=\"article-body\">\n          <div class=\"article-meta\">OpenAI / Cyber <span>6 Nov 2026</span></div>\n          <h3>OpenAI GPT-6 Cyber for authorised scoped vulnerability research (5 Nov).</h3>\n          <p class=\"summary\">OpenAI company blog, 5 November 2026. GPT-6 Cyber is a cybersecurity-specialised model trained to find and validate exploitable vulnerabilities while staying inside researcher-set scope. On ExploitGym it scored 48.5% versus 32.1% for GPT-5.6 Cyber (about a 51% relative improvement). In a scope-alignment evaluation it avoided out-of-scope exploitation in 99.93% of tests without a deployment prompt and 100% with the prompt. OpenAI classifies its cybersecurity capability as Critical under its Preparedness Framework, restricts deeper Daybreak Red access initially to approved customers, and says the model has already helped find issues in codebases such as Linux and Firefox. Mainline models still cover lighter code review and triage.</p>\n          <div class=\"card-actions\">\n            <a class=\"read-more\" href=\"/news/2026-11-06-openai-gpt-6-cyber.html\">Read full article</a>\n            <div class=\"reaction-row\"><a class=\"reaction\" href=\"https://openai.com/index/introducing-gpt-6-cyber\" target=\"_blank\" rel=\"noopener\">Source: OpenAI</a><span class=\"reaction\">agents are useful with limited access, logged actions, and a person approving live sends.</span></div>\n          </div>\n        </div>\n      </article>\n\n      ");
document.getElementById("newsList").insertAdjacentHTML("beforeend", "<article class=\"news-card\" style=\"--stripe:#06b6d4;--thumb-a:#0c2a3e;--thumb-b:#071822\" data-search=\"palo alto networks clutch security talks 500m agent access marina temkin the information\">\n        <a class=\"thumb\" href=\"/news/2026-11-06-palo-alto-clutch-agent-security-talks.html\" aria-label=\"Read: Palo Alto Networks in talks to buy Clutch Security ~$500m (5 Nov).\">\n          <div class=\"thumb-inner\">P</div>\n        </a>\n        <div class=\"article-body\">\n          <div class=\"article-meta\">Palo Alto / Security <span>6 Nov 2026</span></div>\n          <h3>Palo Alto Networks in talks to buy Clutch Security ~$500m (5 Nov).</h3>\n          <p class=\"summary\">TechCrunch, 5 November 2026 (Marina Temkin). Palo Alto Networks is in talks to acquire Clutch Security, which secures AI agents' access to company systems, for about $500 million in cash plus milestone payouts, according to a person familiar with the discussions. Clutch was last valued at $85 million after a $20 million Series A in January 2025 and is approaching about $10 million ARR. Neither company commented. The Information first reported the talks. This is not a closed deal.</p>\n          <div class=\"card-actions\">\n            <a class=\"read-more\" href=\"/news/2026-11-06-palo-alto-clutch-agent-security-talks.html\">Read full article</a>\n            <div class=\"reaction-row\"><a class=\"reaction\" href=\"https://techcrunch.com/2026/11/05/palo-alto-networks-in-talks-to-buy-ai-agent-security-startup-clutch-for-500m/\" target=\"_blank\" rel=\"noopener\">Source: TechCrunch</a><span class=\"reaction\">agents are useful with limited access, logged actions, and a person approving live sends.</span></div>\n          </div>\n        </div>\n      </article>\n\n      ");
document.getElementById("newsList").insertAdjacentHTML("beforeend", "<article class=\"news-card\" style=\"--stripe:#f59e0b;--thumb-a:#3d2000;--thumb-b:#1c0e00\" data-search=\"dropbox tigris data 350m dbx agent cloud object storage s3 lauren forristal\">\n        <a class=\"thumb\" href=\"/news/2026-11-06-dropbox-tigris-dbx-agent-cloud.html\" aria-label=\"Read: Dropbox plans to acquire Tigris Data ~$350m for DBX Agent Cloud (5 Nov).\">\n          <div class=\"thumb-inner\">D</div>\n        </a>\n        <div class=\"article-body\">\n          <div class=\"article-meta\">Dropbox / Storage <span>6 Nov 2026</span></div>\n          <h3>Dropbox plans to acquire Tigris Data ~$350m for DBX Agent Cloud (5 Nov).</h3>\n          <p class=\"summary\">Dropbox company press release / company blog and TechCrunch, 5 November 2026. Dropbox announced plans to acquire Tigris Data for about $350 million (price as reported by TechCrunch's Lauren Forristal and in Dropbox's SEC Q3 materials; company Business Wire / blog frame it as a planned acquisition). The deal is meant to strengthen AI infrastructure and support DBX Agent Cloud, storage aimed at businesses and developers building AI models and agents. Close expected in Q4 2026, subject to customary conditions — not closed yet. TechCrunch reported Dropbox said it has no current plans to cut headcount from the deal. DBX Agent Cloud will initially offer object storage as a stand-alone product compatible with S3-style tools. Dropbox is also expanding AI in its core product (tasking AI on files, choosing models, connecting content to third-party tools including ChatGPT, Claude and Muse). An updated AI experience has reached more than 70,000 teams; initial rollout for eligible Standard and Advanced customers in the US, UK and Australia, with broader availability planned for 2027.</p>\n          <div class=\"card-actions\">\n            <a class=\"read-more\" href=\"/news/2026-11-06-dropbox-tigris-dbx-agent-cloud.html\">Read full article</a>\n            <div class=\"reaction-row\"><a class=\"reaction\" href=\"https://blog.dropbox.com/topics/company/dropboxs-next-chapter\" target=\"_blank\" rel=\"noopener\">Source: Dropbox</a><span class=\"reaction\">agents are useful with limited access, logged actions, and a person approving live sends.</span></div>\n          </div>\n        </div>\n      </article>\n\n      ");
document.getElementById("newsList").insertAdjacentHTML("beforeend", "<article class=\"news-card\" style=\"--stripe:#ef4444;--thumb-a:#3a0a0a;--thumb-b:#1a0404\" data-search=\"perplexity teammates always-on work agents max web ios computer enterprise\">\n        <a class=\"thumb\" href=\"/news/2026-11-06-perplexity-teammates-launch.html\" aria-label=\"Read: Perplexity Teammates always-on work agents (4–5 Nov).\">\n          <div class=\"thumb-inner\">P</div>\n        </a>\n        <div class=\"article-body\">\n          <div class=\"article-meta\">Perplexity / Agents <span>6 Nov 2026</span></div>\n          <h3>Perplexity Teammates always-on work agents (4–5 Nov).</h3>\n          <p class=\"summary\">Perplexity company blog, 4 November 2026 (covered widely 5 Nov). Teammates are personal agents that own ongoing work: plan and coordinate projects, monitor connected tools, collaborate with other agents, and bring results back for review. They build on Perplexity Computer (tools, files, connectors) and add persistent responsibility rather than one-off sessions. Initial research preview is for individual Perplexity Max subscribers on the web; iOS later. Enterprise plans are not included by default at launch (help centre: Enterprise Pro / Enterprise Max need admin request).</p>\n          <div class=\"card-actions\">\n            <a class=\"read-more\" href=\"/news/2026-11-06-perplexity-teammates-launch.html\">Read full article</a>\n            <div class=\"reaction-row\"><a class=\"reaction\" href=\"https://www.perplexity.ai/hub/blog/teammates-are-agents-for-complex-ongoing-work\" target=\"_blank\" rel=\"noopener\">Source: Perplexity</a><span class=\"reaction\">agents are useful with limited access, logged actions, and a person approving live sends.</span></div>\n          </div>\n        </div>\n      </article>\n\n      ");
document.getElementById("newsList").insertAdjacentHTML("beforeend", "<article class=\"news-card\" style=\"--stripe:#10b981;--thumb-a:#064e3b;--thumb-b:#051e16\" data-search=\"mistral studio managed agents enterprise apps sandboxes subagents approval vpc on-premises public preview\">\n        <a class=\"thumb\" href=\"/news/2026-11-06-mistral-studio-managed-agents-apps.html\" aria-label=\"Read: Mistral Studio managed agents and enterprise apps (5 Nov).\">\n          <div class=\"thumb-inner\">M</div>\n        </a>\n        <div class=\"article-body\">\n          <div class=\"article-meta\">Mistral / Studio <span>6 Nov 2026</span></div>\n          <h3>Mistral Studio managed agents and enterprise apps (5 Nov).</h3>\n          <p class=\"summary\">Mistral company announcement, 5 November 2026. Mistral Studio adds managed agents and apps alongside workflow, enterprise context, observability and evaluation tools. Agents can run multi-step work with skills, sandboxes and subagents; developers can require approval for selected tool calls. The pitch covers deployments on Mistral Cloud, VPC, on-premises or mixed — private cloud / on-prem paths are part of the controlled-rollout pitch rather than a claim that every component is already self-hosted everywhere. Apps get hosting, authentication and access controls so internal tools can sit on the same stack. Apps and Managed Agents are in public preview.</p>\n          <div class=\"card-actions\">\n            <a class=\"read-more\" href=\"/news/2026-11-06-mistral-studio-managed-agents-apps.html\">Read full article</a>\n            <div class=\"reaction-row\"><a class=\"reaction\" href=\"https://mistral.ai/news/build-with-studio/\" target=\"_blank\" rel=\"noopener\">Source: Mistral</a><span class=\"reaction\">agents are useful with limited access, logged actions, and a person approving live sends.</span></div>\n          </div>\n        </div>\n      </article>\n\n      ");
