document.getElementById("newsList").insertAdjacentHTML("beforeend", "<article class=\"news-card\" style=\"--stripe:#e60ba0;--thumb-a:#3a0825;--thumb-b:#1e0413\" data-search=\"bcc british chambers of commerce ai adoption gdp modelling anthropic 2031 shevaun haviland bdo summit\">\n        <a class=\"thumb\" href=\"/news/2026-11-05-bcc-ai-adoption-gdp-modelling.html\" aria-label=\"Read: BCC modelling: wider AI adoption could lift UK GDP &gt;10% by 2031 (4 Nov).\">\n          <div class=\"thumb-inner\">B</div>\n        </a>\n        <div class=\"article-body\">\n          <div class=\"article-meta\">BCC / Economy <span>5 Nov 2026</span></div>\n          <h3>BCC modelling: wider AI adoption could lift UK GDP &gt;10% by 2031 (4 Nov).</h3>\n          <p class=\"summary\">British Chambers of Commerce press release, 4 November 2026. New modelling for the BCC, based on two Anthropic adoption scenarios, finds that higher AI adoption (productivity up 57% across 12% of work tasks by 2030) could leave UK GDP more than 10% higher by the end of 2031 than otherwise; a moderate path (35% productivity boost across 4% of tasks) would leave GDP around 2% higher. The BCC also published a book of essays with BDO on how the UK can become an AI adoption superpower, and plans an AI Adoption Summit in London on Tuesday 8 December. Director General Shevaun Haviland said the Budget's AI infrastructure spend was welcome but business adoption is &quot;the missing piece&quot;.</p>\n          <div class=\"card-actions\">\n            <a class=\"read-more\" href=\"/news/2026-11-05-bcc-ai-adoption-gdp-modelling.html\">Read full article</a>\n            <div class=\"reaction-row\"><a class=\"reaction\" href=\"https://www.britishchambers.org.uk/news/2026/11/wider-ai-adoption-could-boost-gdp-by-10/\" target=\"_blank\" rel=\"noopener\">Source: British Chambers of Commerce</a><span class=\"reaction\">Scenarios not promises</span></div>\n          </div>\n        </div>\n      </article>\n\n      ");
document.getElementById("newsList").insertAdjacentHTML("beforeend", "<article class=\"news-card\" style=\"--stripe:#06b6d4;--thumb-a:#0c2a3e;--thumb-b:#071822\" data-search=\"fireworks era4 chesterfield derbyshire uk open models 5mw blackwell landfill gas\">\n        <a class=\"thumb\" href=\"/news/2026-11-05-fireworks-era4-chesterfield-uk-open-models.html\" aria-label=\"Read: Fireworks contracts Era4 Chesterfield 5MW for UK-hosted open models (4 Nov).\">\n          <div class=\"thumb-inner\">F</div>\n        </a>\n        <div class=\"article-body\">\n          <div class=\"article-meta\">Fireworks / Infrastructure <span>5 Nov 2026</span></div>\n          <h3>Fireworks contracts Era4 Chesterfield 5MW for UK-hosted open models (4 Nov).</h3>\n          <p class=\"summary\">Networking+, 4 November 2026. Fireworks and Era4 announced a multi-year agreement under which Fireworks has contracted Era4's entire Chesterfield facility in Derbyshire (5MW direct liquid-cooled capacity with NVIDIA Blackwell Ultra HGX B300 GPUs); Fireworks is already live there. The aim is UK and European enterprises running and adapting open AI models on UK infrastructure, initially exploring financial services, insurance and life sciences uses such as underwriting, financial-crime checks and claims handling. Era4 says most of the site's electricity comes from on-site landfill gas generation, with a grid backup.</p>\n          <div class=\"card-actions\">\n            <a class=\"read-more\" href=\"/news/2026-11-05-fireworks-era4-chesterfield-uk-open-models.html\">Read full article</a>\n            <div class=\"reaction-row\"><a class=\"reaction\" href=\"https://networkingplus.co.uk/fireworks-contracts-era4s-5mw-chesterfield-ai-data-centre-for-uk-hosted-open-models/\" target=\"_blank\" rel=\"noopener\">Source: Networking+</a><span class=\"reaction\">Scenarios not promises</span></div>\n          </div>\n        </div>\n      </article>\n\n      ");
document.getElementById("newsList").insertAdjacentHTML("beforeend", "<article class=\"news-card\" style=\"--stripe:#f59e0b;--thumb-a:#3d2000;--thumb-b:#1c0e00\" data-search=\"openwork advisoryai adviser evie atlas suitability reports compliance telford askham gurung\">\n        <a class=\"thumb\" href=\"/news/2026-11-05-openwork-advisoryai-adviser-ai.html\" aria-label=\"Read: Openwork partners with AdvisoryAI; AI adviser reports and compliance checks planned (4 Nov).\">\n          <div class=\"thumb-inner\">O</div>\n        </a>\n        <div class=\"article-body\">\n          <div class=\"article-meta\">Openwork / Advisers <span>5 Nov 2026</span></div>\n          <h3>Openwork partners with AdvisoryAI; AI adviser reports and compliance checks planned (4 Nov).</h3>\n          <p class=\"summary\">Money Marketing, 4 November 2026 (Momodou Musa Touray). Openwork announced a partnership with AdvisoryAI at its Advice Conference in Telford. Advisers can already use AdvisoryAI's meeting-notes assistant Evie and Atlas (opportunity spotting from notes) via Openwork's digital marketplace. Planned further functions include AI-generated suitability reports, annual review letters and compliance checks to flag file gaps before cases reach compliance teams, with a longer-term goal of producing suitability reports inside Openwork's own suite. Openwork chief commercial officer Rob Askham and AdvisoryAI CEO Alan Gurung both framed the aim as cutting admin so advisers can spend more time with clients.</p>\n          <div class=\"card-actions\">\n            <a class=\"read-more\" href=\"/news/2026-11-05-openwork-advisoryai-adviser-ai.html\">Read full article</a>\n            <div class=\"reaction-row\"><a class=\"reaction\" href=\"https://www.moneymarketing.co.uk/news/openwork-expands-ai-offering-with-advisoryai/\" target=\"_blank\" rel=\"noopener\">Source: Money Marketing</a><span class=\"reaction\">Scenarios not promises</span></div>\n          </div>\n        </div>\n      </article>\n\n      ");
document.getElementById("newsList").insertAdjacentHTML("beforeend", "<article class=\"news-card\" style=\"--stripe:#ef4444;--thumb-a:#3a0a0a;--thumb-b:#1a0404\" data-search=\"openai images 2.6 gifs chatgpt flare sunburst gpt-image-2.6\">\n        <a class=\"thumb\" href=\"/news/2026-11-05-openai-images-2-6-gifs-chatgpt.html\" aria-label=\"Read: OpenAI Images 2.6 brings GIFs to ChatGPT (4 Nov).\">\n          <div class=\"thumb-inner\">O</div>\n        </a>\n        <div class=\"article-body\">\n          <div class=\"article-meta\">OpenAI / Product <span>5 Nov 2026</span></div>\n          <h3>OpenAI Images 2.6 brings GIFs to ChatGPT (4 Nov).</h3>\n          <p class=\"summary\">OpenAI company blog, 4 November 2026. Images 2.6 is available in ChatGPT, Codex and the API across all ChatGPT/Codex subscription tiers on desktop, mobile and web. Users can create animated GIFs from a prompt or turn an image, such as a product shot, into a loop. OpenAI says image generation is about 50% faster than before. API models GPT-Image-2.6 Flare (speed) and Sunburst (higher quality/consistency) are also available. OpenAI says people create about 4 billion images per week across ChatGPT, Codex and the API.</p>\n          <div class=\"card-actions\">\n            <a class=\"read-more\" href=\"/news/2026-11-05-openai-images-2-6-gifs-chatgpt.html\">Read full article</a>\n            <div class=\"reaction-row\"><a class=\"reaction\" href=\"https://openai.com/index/introducing-images-2-6/\" target=\"_blank\" rel=\"noopener\">Source: OpenAI</a><span class=\"reaction\">Scenarios not promises</span></div>\n          </div>\n        </div>\n      </article>\n\n      ");
document.getElementById("newsList").insertAdjacentHTML("beforeend", "<article class=\"news-card\" style=\"--stripe:#10b981;--thumb-a:#064e3b;--thumb-b:#051e16\" data-search=\"wired uk 400bn google public first pf global kanishka narayan 55 140 billion onwurah\">\n        <a class=\"thumb\" href=\"/news/2026-11-05-wired-uk-ai-400bn-google-commissioned-figure.html\" aria-label=\"Read: WIRED on UK £400bn AI figure vs official £55-140bn range (4 Nov).\">\n          <div class=\"thumb-inner\">W</div>\n        </a>\n        <div class=\"article-body\">\n          <div class=\"article-meta\">WIRED / Policy <span>5 Nov 2026</span></div>\n          <h3>WIRED on UK £400bn AI figure vs official £55-140bn range (4 Nov).</h3>\n          <p class=\"summary\">WIRED, 4 November 2026. For about two years UK officials cited a possible £400 billion AI economic boost drawn from a 2023 Public First (now PF Global) report commissioned by Google. AI minister Kanishka Narayan, answering a parliamentary question, said a more recent government assessment put the range at £55 billion to £140 billion by 2030 (central estimate about £120 billion), and called even that &quot;hugely uncertain&quot;. PF Global's Jonathan Dupont told WIRED the gap partly reflects slower adoption assumptions than in 2023. Dame Chi Onwurah warned against hype that undermines the case for change.</p>\n          <div class=\"card-actions\">\n            <a class=\"read-more\" href=\"/news/2026-11-05-wired-uk-ai-400bn-google-commissioned-figure.html\">Read full article</a>\n            <div class=\"reaction-row\"><a class=\"reaction\" href=\"https://www.wired.com/story/uk-officials-said-ai-would-add-400-billion-to-the-economy-that-figure-mainly-came-from-google/\" target=\"_blank\" rel=\"noopener\">Source: WIRED</a><span class=\"reaction\">Scenarios not promises</span></div>\n          </div>\n        </div>\n      </article>\n\n      ");
