document.getElementById("newsList").insertAdjacentHTML("beforeend", "<article class=\"news-card\" style=\"--stripe:#ef4444;--thumb-a:#3a0a0a;--thumb-b:#1a0404\" data-search=\"openai moonshot adversarial distillation kimi protected reasoning extraction campaign\">\n        <a class=\"thumb image-thumb\" href=\"/news/2026-10-02-openai-moonshot-adversarial-distillation.html\" aria-label=\"Read: OpenAI disrupts Moonshot-linked reasoning extraction campaign\">\n          <img src=\"/news/img/2026-10-02-openai-moonshot-adversarial-distillation.png\" width=\"1376\" height=\"768\" alt=\"OpenAI disrupts a Moonshot-linked campaign to extract protected model reasoning — 2 Oct 2026\">\n        </a>\n        <div class=\"article-body\">\n          <div class=\"article-meta\">OpenAI / Security <span>2 Oct 2026</span></div>\n          <h3>OpenAI disrupts Moonshot-linked reasoning extraction campaign</h3>\n          <p class=\"summary\">OpenAI said it disrupted a coordinated adversarial-distillation campaign to extract protected reasoning, attributing a core cluster to individuals associated with Moonshot AI. Activity peaked at 16,000 requests from more than 4,000 users over two July days; operators did not breach encryption or databases.</p>\n          <div class=\"card-actions\">\n            <a class=\"read-more\" href=\"/news/2026-10-02-openai-moonshot-adversarial-distillation.html\">Read full article</a>\n            <div class=\"reaction-row\"><a class=\"reaction\" href=\"https://openai.com/index/disrupting-a-coordinated-model-distillation-campaign/\" target=\"_blank\" rel=\"noopener\">Source: OpenAI / CNBC</a><span class=\"reaction\">Oversight</span></div>\n          </div>\n        </div>\n      </article>\n\n      ");
document.getElementById("newsList").insertAdjacentHTML("beforeend", "<article class=\"news-card\" style=\"--stripe:#10b981;--thumb-a:#064e3b;--thumb-b:#051e16\" data-search=\"bank of england bailey ai testing before regulation uk ai security institute\">\n        <a class=\"thumb image-thumb\" href=\"/news/2026-10-02-bank-of-england-bailey-ai-testing-before-regulation.html\" aria-label=\"Read: BoE’s Bailey: regulating AI not the right place to start\">\n          <img src=\"/news/img/2026-10-02-bank-of-england-bailey-ai-testing-before-regulation.png\" width=\"1376\" height=\"768\" alt=\"Bank of England Governor Andrew Bailey argues for AI testing before regulation — 2 Oct 2026\">\n        </a>\n        <div class=\"article-body\">\n          <div class=\"article-meta\">Bank of England / Regulation <span>2 Oct 2026</span></div>\n          <h3>BoE’s Bailey: regulating AI not the right place to start</h3>\n          <p class=\"summary\">Andrew Bailey argued for rigorous testing, intervention points, and standards work — including via the UK AI Security Institute — before rushing to new AI regulation. He said benefits are immense, risks are real, and unexpected model behaviour in tests is why testing is necessary.</p>\n          <div class=\"card-actions\">\n            <a class=\"read-more\" href=\"/news/2026-10-02-bank-of-england-bailey-ai-testing-before-regulation.html\">Read full article</a>\n            <div class=\"reaction-row\"><a class=\"reaction\" href=\"https://www.bbc.co.uk/news/articles/cvzez7k0pn40o\" target=\"_blank\" rel=\"noopener\">Source: BBC</a><span class=\"reaction\">Oversight</span></div>\n          </div>\n        </div>\n      </article>\n\n      <!-- ===== 28 SEP 2026 ===== -->\n      ");
