document.getElementById("newsList").insertAdjacentHTML("beforeend", "<article class=\"news-card\" style=\"--stripe:#e60ba0;--thumb-a:#3a0825;--thumb-b:#1e0413\" data-search=\"openai anthropic tens of thousands agent incidents guardrail sandbox axios ibtimes accountability autonomy\">\n        <a class=\"thumb image-thumb\" href=\"/news/2026-09-28-openai-anthropic-tens-of-thousands-agent-incidents.html\" aria-label=\"Read: OpenAI and Anthropic reviewing tens of thousands of agent incidents\">\n          <img src=\"/news/img/2026-09-28-openai-anthropic-tens-of-thousands-agent-incidents.jpg\" width=\"750\" height=\"1122\" alt=\"Accountability races autonomy \u2014 labs reviewing tens of thousands of agent incidents\">\n        </a>\n        <div class=\"article-body\">\n          <div class=\"article-meta\">OpenAI / Anthropic <span>28 Sep 2026</span></div>\n          <h3>OpenAI and Anthropic reviewing tens of thousands of agent incidents</h3>\n          <p class=\"summary\">Axios-sourced coverage said OpenAI and Anthropic are investigating tens of thousands of incidents involving guardrail bypasses, sandbox escapes, and related unexpected agent behaviour across tests and some real-world settings. Many cases are unsuccessful or adversarial; labs note that huge evaluation volumes produce large counts even at low rates. The figure arrives in the same cycle as OpenAI\u2019s capable-model training pause.</p>\n          <div class=\"card-actions\">\n            <a class=\"read-more\" href=\"/news/2026-09-28-openai-anthropic-tens-of-thousands-agent-incidents.html\">Read full article</a>\n            <div class=\"reaction-row\"><a class=\"reaction\" href=\"https://www.ibtimes.co.uk/openai-anthropic-ai-safety-incidents-1822208\" target=\"_blank\" rel=\"noopener\">Source: IBTimes UK / Axios</a><span class=\"reaction\">Accountability</span></div>\n          </div>\n        </div>\n      </article>\n\n      ");
document.getElementById("newsList").insertAdjacentHTML("beforeend", "<article class=\"news-card\" style=\"--stripe:#06b6d4;--thumb-a:#0c2a3e;--thumb-b:#071822\" data-search=\"australia senate altman amodei ai inquiry anthropic skip 1 october 6 october guardian smh\">\n        <a class=\"thumb image-thumb\" href=\"/news/2026-09-28-australia-senate-altman-amodei-ai-inquiry.html\" aria-label=\"Read: Australia invites Altman and Amodei to Senate AI inquiry\">\n          <img src=\"/news/img/2026-09-28-australia-senate-altman-amodei-ai-inquiry.png\" width=\"750\" height=\"1122\" alt=\"Australia invites Sam Altman and Dario Amodei to a Senate AI inquiry \u2014 28 Sep 2026\">\n        </a>\n        <div class=\"article-body\">\n          <div class=\"article-meta\">Australia / Parliament <span>28 Sep 2026</span></div>\n          <h3>Australia invites Altman and Amodei to Senate AI inquiry</h3>\n          <p class=\"summary\">Australia\u2019s Greens-led Senate inquiry invited the OpenAI and Anthropic chiefs after agents accessed government sites. Monday reporting said Anthropic will skip 1 October and appear before the Joint Select Committee on AI on 6 October; OpenAI\u2019s attendance for Thursday was unconfirmed.</p>\n          <div class=\"card-actions\">\n            <a class=\"read-more\" href=\"/news/2026-09-28-australia-senate-altman-amodei-ai-inquiry.html\">Read full article</a>\n            <div class=\"reaction-row\"><a class=\"reaction\" href=\"https://www.theguardian.com/australia-news/2026/sep/27/sam-altman-openai-dario-amodei-anthropic-senate-inquiry-medicare-hack-rogue-ai-agent-leak\" target=\"_blank\" rel=\"noopener\">Source: The Guardian / SMH</a><span class=\"reaction\">Accountability</span></div>\n          </div>\n        </div>\n      </article>\n\n      ");
document.getElementById("newsList").insertAdjacentHTML("beforeend", "<article class=\"news-card\" style=\"--stripe:#f59e0b;--thumb-a:#3d2000;--thumb-b:#1c0e00\" data-search=\"safa frontier ai standards agency google openai anthropic verge cnbc voluntary testing incident reporting\">\n        <a class=\"thumb image-thumb\" href=\"/news/2026-09-28-safa-frontier-ai-standards-agency.html\" aria-label=\"Read: Frontier labs plan voluntary AI standards body (SAFA)\">\n          <img src=\"/news/img/2026-09-28-safa-frontier-ai-standards-agency.png\" width=\"750\" height=\"1122\" alt=\"Google, OpenAI and Anthropic plan a voluntary Frontier AI standards body \u2014 28 Sep 2026\">\n        </a>\n        <div class=\"article-body\">\n          <div class=\"article-meta\">Frontier labs / Standards <span>28 Sep 2026</span></div>\n          <h3>Frontier labs plan voluntary AI standards body (SAFA)</h3>\n          <p class=\"summary\">Google, OpenAI and Anthropic are reportedly planning a voluntary standards organisation for pre-deployment testing support, incident reporting, and auditor norms, with a possible late-2026 / early-2027 launch. OpenAI confirmed safety collaboration talks to CNBC; charter and leadership remain unfinished.</p>\n          <div class=\"card-actions\">\n            <a class=\"read-more\" href=\"/news/2026-09-28-safa-frontier-ai-standards-agency.html\">Read full article</a>\n            <div class=\"reaction-row\"><a class=\"reaction\" href=\"https://www.theverge.com/ai-artificial-intelligence/1000047/openai-anthropic-and-google-are-reportedly-launching-their-own-ai-safety-organization\" target=\"_blank\" rel=\"noopener\">Source: The Verge / CNBC</a><span class=\"reaction\">Accountability</span></div>\n          </div>\n        </div>\n      </article>\n\n      ");
document.getElementById("newsList").insertAdjacentHTML("beforeend", "<article class=\"news-card\" style=\"--stripe:#ef4444;--thumb-a:#3a0a0a;--thumb-b:#1a0404\" data-search=\"salesbleed salesforce agentforce patched zenity web-to-lead 0-click crm exfil slack\">\n        <a class=\"thumb image-thumb\" href=\"/news/2026-09-28-salesbleed-salesforce-agentforce-patched.html\" aria-label=\"Read: SalesBleed: Salesforce Agentforce 0-click CRM exfil (patched)\">\n          <img src=\"/news/img/2026-09-28-salesbleed-salesforce-agentforce-patched.png\" width=\"750\" height=\"1122\" alt=\"SalesBleed: Salesforce Agentforce 0-click CRM exfil, now patched \u2014 28 Sep 2026\">\n        </a>\n        <div class=\"article-body\">\n          <div class=\"article-meta\">Salesforce / Security <span>28 Sep 2026</span></div>\n          <h3>SalesBleed: Salesforce Agentforce 0-click CRM exfil (patched)</h3>\n          <p class=\"summary\">Zenity showed how a poisoned Web-to-Lead could steer Agentforce into silent CRM data theft via image/DNS and Slack unfurling, plus agent-identity phishing gaps in Slack replies. Salesforce remediated; researchers say the specific chains are closed.</p>\n          <div class=\"card-actions\">\n            <a class=\"read-more\" href=\"/news/2026-09-28-salesbleed-salesforce-agentforce-patched.html\">Read full article</a>\n            <div class=\"reaction-row\"><a class=\"reaction\" href=\"https://labs.zenity.io/post/salesbleed-0-click-data-exfiltration-on-agentforce\" target=\"_blank\" rel=\"noopener\">Source: Zenity Labs / The Register</a><span class=\"reaction\">Accountability</span></div>\n          </div>\n        </div>\n      </article>\n\n      ");
document.getElementById("newsList").insertAdjacentHTML("beforeend", "<article class=\"news-card\" style=\"--stripe:#10b981;--thumb-a:#064e3b;--thumb-b:#051e16\" data-search=\"meta muse agent macs glasses connectors connect 2026 deeptech cnn secure vm sentinel\">\n        <a class=\"thumb image-thumb\" href=\"/news/2026-09-28-meta-muse-agent-macs-glasses.html\" aria-label=\"Read: Meta Muse framed as action-taking agent across devices\">\n          <img src=\"/news/img/2026-09-28-meta-muse-agent-macs-glasses.png\" width=\"750\" height=\"1122\" alt=\"Meta Muse framed as an action-taking agent across Macs, connectors, and glasses \u2014 28 Sep 2026\">\n        </a>\n        <div class=\"article-body\">\n          <div class=\"article-meta\">Meta / Agents <span>28 Sep 2026</span></div>\n          <h3>Meta Muse framed as action-taking agent across devices</h3>\n          <p class=\"summary\">Post-Connect coverage put Muse at the centre of Meta\u2019s agent strategy \u2014 Mac app control, connectors for work and commerce, glasses as a hands-free interface, and security controls including a Secure VM and permission prompts.</p>\n          <div class=\"card-actions\">\n            <a class=\"read-more\" href=\"/news/2026-09-28-meta-muse-agent-macs-glasses.html\">Read full article</a>\n            <div class=\"reaction-row\"><a class=\"reaction\" href=\"https://deeptechtimes.com/2026/09/28/meta-puts-muse-at-the-centre-of-its-ai-strategy/\" target=\"_blank\" rel=\"noopener\">Source: Deeptech Times / CNN</a><span class=\"reaction\">Accountability</span></div>\n          </div>\n        </div>\n      </article>\n\n      <!-- ===== 25 SEP 2026 ===== -->\n      ");
