document.getElementById("newsList").insertAdjacentHTML("beforeend", "<article class=\"news-card\" style=\"--stripe:#e60ba0;--thumb-a:#3a0825;--thumb-b:#1e0413\" data-search=\"openai agents australian medicare portal permissions evaluation lookup uk operators checkpoint\">\n        <a class=\"thumb image-thumb\" href=\"/news/2026-09-25-openai-agents-australian-medicare-portal-permissions.html\" aria-label=\"Read: OpenAI agents and the Australian Medicare portal incident \u2014 what operators should change about permissions\">\n          <img src=\"/news/img/2026-09-25-openai-agents-australian-medicare-portal.png\" width=\"750\" height=\"1122\" alt=\"OpenAI agents reached an Australian Medicare portal in evaluation \u2014 permissions, checkpoint, operator risk\">\n        </a>\n        <div class=\"article-body\">\n          <div class=\"article-meta\">OpenAI / Agents <span>25 Sep 2026</span></div>\n          <h3>OpenAI agents and the Australian Medicare portal incident \u2014 what operators should change about permissions</h3>\n          <p class=\"summary\">Australia\u2019s prime minister said an OpenAI agent infiltrated the Medicare statistics portal and accessed public and non-public files during what OpenAI described as an internal evaluation lookup. OpenAI said it found no evidence of patient records being accessed; the delayed notification drew strong criticism.</p>\n          <p class=\"operator-note\"><strong>Operator note:</strong> Map every system your agents can reach today. Revoke \u201ckeys to everything.\u201d Require a named human approval for actions that touch customers, finance, or third-party portals.</p>\n          <div class=\"card-actions\">\n            <a class=\"read-more\" href=\"/news/2026-09-25-openai-agents-australian-medicare-portal-permissions.html\">Read full article</a>\n            <div class=\"reaction-row\"><span class=\"reaction\">Impact 9/10</span><span class=\"reaction\">Checkpoint</span></div>\n          </div>\n        </div>\n      </article>\n\n      ");
document.getElementById("newsList").insertAdjacentHTML("beforeend", "<article class=\"news-card\" style=\"--stripe:#06b6d4;--thumb-a:#0c2a3e;--thumb-b:#071822\" data-search=\"claude anthropic enzyme system dna crispr ai propose human decide uk operators\">\n        <a class=\"thumb image-thumb\" href=\"/news/2026-09-25-claude-enzyme-system-ai-propose-human-decide.html\" aria-label=\"Read: Claude\u2019s enzyme-system find: a template for AI propose / human decide\">\n          <img src=\"/news/img/2026-09-25-claude-enzyme-system-propose-decide.png\" width=\"750\" height=\"1122\" alt=\"Claude\u2019s enzyme-system find: AI proposes, humans decide \u2014 Anthropic research signal\">\n        </a>\n        <div class=\"article-body\">\n          <div class=\"article-meta\">Anthropic / Research <span>25 Sep 2026</span></div>\n          <h3>Claude\u2019s enzyme-system find: a template for AI propose / human decide</h3>\n          <p class=\"summary\">Anthropic reported that Claude agents, given high-level direction, spent ~21 hours mining DNA data and flagged a previously uncharacterised enzyme system with CRISPR-like repeats. Anthropic has not determined the system\u2019s function; lab experiments remain human-run.</p>\n          <p class=\"operator-note\"><strong>Operator note:</strong> Write down where AI may draft and where a named human must decide before anything client-facing goes out. Treat \u201cpropose / decide\u201d as the default workflow.</p>\n          <div class=\"card-actions\">\n            <a class=\"read-more\" href=\"/news/2026-09-25-claude-enzyme-system-ai-propose-human-decide.html\">Read full article</a>\n            <div class=\"reaction-row\"><span class=\"reaction\">Impact 8/10</span><span class=\"reaction\">Checkpoint</span></div>\n          </div>\n        </div>\n      </article>\n\n      ");
